    templates = [row[:] for row in grid if 2 not in row]

    result = []
    for r in grid:
        # Find a matching template for the current row
        match = None
        for t in templates:
            # Check compatibility: for every index, if r has a non-2 value, it must match t
            compatible = True
            for i in range(len(r)):
